describe('Hydro Wave mob skill',function()
 it('uses its Water magical plan, conditionally unequips, and always sets water Stoneskin',function()
  local wave=require('scripts/actions/mobskills/hydro_wave');local move,process,unequip=xi.mobskills.mobMagicalMove,xi.mobskills.processDamage,xi.mobskills.unequipRandomSlots;local params,damage,unequipped,deleted,added,final=nil,nil,nil,nil,nil,nil;local mob={getMainLvl=function()return 75 end,delStatusEffectSilent=function(_,effect)deleted=effect end,addStatusEffect=function(_,effect,options)added={effect,options}end};local target={takeDamage=function(_,...)damage={...}end};local skill={setFinalAnimationSub=function(_,value)final=value end};xi.mobskills.mobMagicalMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.MAGICAL,damageType=xi.damageType.WATER}end;xi.mobskills.processDamage=function()return false end;xi.mobskills.unequipRandomSlots=function(_,count)unequipped=count end
  assert(wave.onMobSkillCheck(target,mob,skill)==0 and wave.onMobWeaponSkill(mob,target,skill,{})==123);assert(params.baseDamage==77 and params.fTP[1]==2.5 and params.fTP[2]==2.5 and params.fTP[3]==2.5 and params.element==xi.element.WATER and params.attackType==xi.attackType.MAGICAL and params.damageType==xi.damageType.WATER and params.shadowBehavior==xi.mobskills.shadowBehavior.WIPE_SHADOWS and damage==nil and unequipped==nil and final==2 and deleted==xi.effect.STONESKIN and added[1]==xi.effect.STONESKIN and added[2].duration==180 and added[2].origin==mob and added[2].subType==2 and added[2].subPower==1500);xi.mobskills.processDamage=function()return true end;wave.onMobWeaponSkill(mob,target,skill,{})
  xi.mobskills.mobMagicalMove,xi.mobskills.processDamage,xi.mobskills.unequipRandomSlots=move,process,unequip;assert(damage[1]==123 and damage[2]==mob and damage[3]==xi.attackType.MAGICAL and damage[4]==xi.damageType.WATER and unequipped==1)
 end)
end)
